style.css:
@-moz-document domain("roblox.com") {
html, body {
        background: url("https://i.imgur.com/WR4Okai.jpeg") no-repeat center center fixed !important;
        background-size: cover !important;
        background-color: black !important; /* color de respaldo */
    }

    /* Quitar fondos sólidos de los contenedores principales */
    .container-main, 
    #rbx-body, 
    .content,
    .rbx-body,
    .container-fluid,
    .section,
    .page-content,
    .content-container,
    .game-cards,
    .game-home-page-content {
        background: transparent !important;
    }

    /* Header, footer y navbar en negro sólido */
    header, 
    footer, 
    nav, 
    .navbar, 
    .footer-container, 
    .menu-container {
        background: #000000 !important;
    }
}
